function firstBad(versions, isBad) {
  let good = -1;
  let bad = versions.length - 1;
  let checks = 0;
  while (bad - good > 1) {
    const middle = Math.floor((good + bad) / 2);
    checks++;
    if (isBad(versions[middle])) bad = middle;
    else good = middle;
  }
  return `${versions[bad]} after ${checks} checks`;
}

