function deepFreeze(value) {
  for (const inner of Object.values(value)) {
    if (inner && typeof inner === "object") deepFreeze(inner);
  }
  return Object.freeze(value);
}

const PROMO = deepFreeze({ percent: 0, rules: [{ sku: "RICE-5", tags: ["food"] }] });
